import type { SagaId } from "./cards";

/**
 * Parte editoriale del database carte, scritta a mano da OriginsMeta e indicizzata per slug:
 * - `saga`: la leggenda da cui viene la carta (le "saghe" sono una classificazione nostra, il gioco non la espone);
 * - `origin`: una riga sull'origine del personaggio, in inglese, italiano e spagnolo;
 * - `it` ed `es`: traduzioni italiana e spagnola del testo ufficiale della carta (l'inglese sta in `woo-cards.json`;
 *   le parole chiave del gioco restano in inglese, come nelle pill del sito).
 * Quando `npm run import:woo` segnala un testo cambiato, vanno aggiornate le righe `it` ed `es` corrispondenti.
 * Lo spagnolo (25/09/2026) è una traduzione nostra dal testo inglese del gioco, sul modello dell'italiano: da
 * confrontare con il gioco (Pierluigi, 25/09/2026: "ti faccio fare un giro sul gioco così recuperi i testi corretti").
 */
export type Lore = {
  saga: SagaId;
  origin?: { en: string; it: string; es: string };
  /**
   * Testo ufficiale inglese letto nel gioco, quando quello di World of Origins è rimasto indietro: vince su
   * `woo-cards.json`. Verifica carta per carta sulla Demo 2.0 del 22/09/2026 (collezione del gioco, 122 carte):
   * le statistiche coincidevano tutte, 16 testi no (effetti cambiati nelle patch 0.6.2/0.6.3 e formulazioni).
   */
  en?: string;
  it?: string;
  es?: string;
  /**
   * Parole chiave quando quelle di World of Origins non corrispondono al testo del gioco: sostituiscono le sue.
   * 24/09/2026: a Queen of Hearts restava "On Reveal" (il testo dice On Death), a Bagheera mancava "On Reveal".
   */
  keywords?: string[];
  /** chiave ufficiale della carta quando World of Origins non la espone (letta dal materiale ufficiale Koin) */
  key?: string;
};

