  "little-john": { saga: "sherwood", origin: { en: "Robin's giant lieutenant, who beat him with a staff on a log bridge before joining him.", it: "Il gigantesco luogotenente di Robin, che lo batté col bastone su un ponte di tronchi prima di unirsi a lui.", es: "El gigantesco lugarteniente de Robin, que lo venció con un bastón sobre un puente de troncos antes de unirse a él." }, it: "On Reveal: Se un nemico è stato giocato qui in questo round, ottengo +2⚔️/+2❤️.", es: "On Reveal: Si se ha jugado un enemigo aquí en esta ronda, obtengo +2⚔️/+2❤️." },
  tuck: { saga: "sherwood", origin: { en: "Friar Tuck, the jovial, hard-drinking monk of the Merry Men.", it: "Frate Tuck, il monaco gioviale e bevitore degli Allegri Compari.", es: "Fray Tuck, el monje jovial y gran bebedor de los Hombres Alegres." }, it: "On Reveal: Se un nemico è stato giocato qui in questo round, pesca una carta.", es: "On Reveal: Si se ha jugado un enemigo aquí en esta ronda, roba una carta." },
  "guy-of-gisborne": { saga: "sherwood", origin: { en: "The bounty hunter in a horse-hide who duels Robin in one of the oldest ballads.", it: "Il cacciatore di taglie vestito di pelle di cavallo che duella con Robin in una delle ballate più antiche.", es: "El cazarrecompensas vestido con una piel de caballo que se bate en duelo con Robin en una de las baladas más antiguas." }, it: "Double Attack, Snipe 1", es: "Double Attack, Snipe 1" },
  "sheriff-of-nottingham": { saga: "sherwood", origin: { en: "Robin Hood's sworn enemy, the corrupt lawman of Nottingham.", it: "Il nemico giurato di Robin Hood, il corrotto tutore della legge di Nottingham.", es: "El enemigo jurado de Robin Hood, el corrupto agente de la ley de Nottingham." }, it: "On Reveal: Stun il nemico di fronte a me.", es: "On Reveal: Aplica Stun al enemigo de enfrente." },
