  "merry-man": { saga: "sherwood", key: "C00011_MB", origin: { en: "One of the Merry Men, Robin Hood's band of outlaws in Lincoln green.", it: "Uno degli Allegri Compari, la banda di fuorilegge di Robin Hood vestita di verde Lincoln.", es: "Uno de los Hombres Alegres, la banda de forajidos de Robin Hood vestida de verde Lincoln." } },
  reinforcements: { saga: "sherwood", origin: { en: "The horn call that brings the Merry Men out of the trees.", it: "Il richiamo del corno che fa uscire gli Allegri Compari dagli alberi.", es: "El toque de cuerno que hace salir a los Hombres Alegres de entre los árboles." }, it: "Evoca un Merry Man [1⚔️/1❤️] su due caselle casuali.", es: "Invoca un Merry Man [1⚔️/1❤️] en dos casillas aleatorias." },
  bullseye: { saga: "sherwood", origin: { en: "The arrow that splits the other arrow: Robin's winning shot at the Sheriff's tournament.", it: "La freccia che spacca l'altra freccia: il tiro vincente di Robin al torneo dello Sceriffo.", es: "La flecha que parte en dos la otra flecha: el tiro ganador de Robin en el torneo del sheriff." }, it: "Infliggi 3 danni a QUALSIASI personaggio.", es: "Inflige 3 de daño a CUALQUIER personaje." },
  "rain-of-arrows": { saga: "other", origin: { en: "A volley from an unseen line of archers.", it: "Una raffica da una fila di arcieri invisibile.", es: "Una andanada desde una fila de arqueros ocultos." }, it: "Infliggi 2 danni a tutti i nemici.", es: "Inflige 2 de daño a todos los enemigos." },

