  "brides-of-dracula": { saga: "gothic", origin: { en: "The three vampire women who share Dracula's castle and nearly drain Jonathan Harker.", it: "Le tre vampire che abitano il castello di Dracula e quasi dissanguano Jonathan Harker.", es: "Las tres vampiras que comparten el castillo de Drácula y casi desangran a Jonathan Harker." }, it: "Quando scarti una carta, infliggo 1 danno alla barriera avversaria qui e ottengo +1❤️.", es: "Cuando descartes una carta, inflijo 1 de daño a la barrera del oponente aquí y obtengo +1❤️." },
  "van-helsing": { saga: "gothic", origin: { en: "Abraham Van Helsing, the Dutch professor who leads the hunt for Dracula.", it: "Abraham Van Helsing, il professore olandese che guida la caccia a Dracula.", es: "Abraham Van Helsing, el profesor holandés que dirige la caza de Drácula." }, en: "Before combat, add Van Helsing's Tools to your hand if it is not already there.", it: "Prima del combattimento, aggiungi Van Helsing's Tools alla tua mano se non è già lì.", es: "Antes del combate, añade Van Helsing's Tools a tu mano si no está ya en ella." },
  "van-helsings-tools": { saga: "gothic", origin: { en: "The vampire hunter's kit: holy water, silver, garlic and a stake.", it: "Il corredo del cacciatore di vampiri: acqua santa, argento, aglio e un paletto.", es: "El equipo del cazador de vampiros: agua bendita, plata, ajo y una estaca." }, it: "Scegli uno: gioca Holy Water OPPURE Silver Bullet OPPURE Garlic OPPURE Wooden Stake.", es: "Elige uno: juega Holy Water O Silver Bullet O Garlic O Wooden Stake." },
