  "sweeney-todd": { saga: "gothic", origin: { en: "The demon barber of Fleet Street, a penny-dreadful villain of 1846 who cuts more than hair.", it: "Il barbiere diabolico di Fleet Street, cattivo da penny dreadful del 1846 che taglia più dei capelli.", es: "El barbero diabólico de Fleet Street, villano de un penny dreadful de 1846 que corta algo más que el pelo." }, it: "Quando attacco, distruggi un alleato o un nemico casuale qui con meno ⚔️ di me.", es: "Cuando ataque, destruye aquí a un aliado o enemigo aleatorio con menos ⚔️ que yo." },
  "mrs-lovett": { saga: "gothic", origin: { en: "Todd's partner, whose meat pies have a secret ingredient.", it: "La socia di Todd, i cui pasticci di carne hanno un ingrediente segreto.", es: "La socia de Todd, cuyos pasteles de carne tienen un ingrediente secreto." }, it: "Quando distruggi un alleato, metti un Cibo sulla sua casella.", es: "Cuando destruyas a un aliado, pon una Comida en su casilla." },
