  imhotep: { saga: "gothic", origin: { en: "The historical architect of Egypt's first pyramid, reimagined as the cursed priest of The Mummy (1932).", it: "L'architetto storico della prima piramide d'Egitto, reinventato come il sacerdote maledetto de La mummia (1932).", es: "El arquitecto histórico de la primera pirámide de Egipto, reimaginado como el sacerdote maldito de La momia (1932)." }, it: "On Death: Infliggi 2 danni a tutti i nemici qui.", es: "On Death: Inflige 2 de daño a todos los enemigos aquí." },
  necromancer: { saga: "gothic", origin: { en: "The sorcerer who raises and commands the dead.", it: "Lo stregone che risveglia e comanda i morti.", es: "El hechicero que levanta a los muertos y los tiene a sus órdenes." }, it: "On Reveal: Scarta una carta casuale per aggiungere 2 Zombie [2⚔️/2❤️] alla tua mano. Se così scarti un personaggio Evil, evoca invece quegli zombie.", es: "On Reveal: Descarta una carta aleatoria para añadir 2 Zombies [2⚔️/2❤️] a tu mano. Si así descartas un personaje Evil, invócalos en su lugar." },
  zombie: { saga: "gothic", origin: { en: "The walking corpse, from Haitian folklore to every graveyard in fiction.", it: "Il cadavere che cammina, dal folclore haitiano a ogni cimitero della finzione.", es: "El cadáver andante, del folclore haitiano a todos los cementerios de la ficción." } },
  "legion-of-the-dead": { saga: "gothic", origin: { en: "An army of the risen dead, the necromancer's last argument.", it: "Un esercito di morti risorti, l'ultimo argomento del negromante.", es: "Un ejército de muertos resucitados, el último argumento del nigromante." }, it: "Riempi il tuo campo di Zombie [2⚔️/2❤️].", es: "Llena tu tablero de Zombies [2⚔️/2❤️]." },

