  mowgli: { saga: "jungle-book", origin: { en: "The man-cub raised by wolves in Kipling's 1894 Jungle Book.", it: "Il cucciolo d'uomo cresciuto dai lupi nel Libro della giungla di Kipling (1894).", es: "El cachorro humano criado por los lobos en El libro de la selva de Kipling (1894)." }, it: "On Reveal: Evoca Baloo [6⚔️/6❤️] in un altro luogo casuale.", es: "On Reveal: Invoca a Baloo [6⚔️/6❤️] en otra ubicación aleatoria." },
  bagheera: { saga: "jungle-book", origin: { en: "The black panther who buys Mowgli's life with a freshly killed bull.", it: "La pantera nera che compra la vita di Mowgli con un toro appena ucciso.", es: "La pantera negra que compra la vida de Mowgli con un toro recién cazado." }, en: "On Reveal: If I'm on a middle space, I get +2⚔️/+2❤️.", it: "On Reveal: Se sono su una casella centrale, ottengo +2⚔️/+2❤️.", es: "On Reveal: Si estoy en una casilla central, obtengo +2⚔️/+2❤️.", keywords: ["On Reveal", "Self Buff"] },
